'use strict';
const $=s=>document.querySelector(s);const state={recall:null,search:null,stroop:null,catch:null};let visibleMs=0,lastVisible=performance.now(),active='search',timers=[],running=false,catchRespond=null;const game=$('#game');
function timeVisible(){return visibleMs+(document.hidden?0:performance.now()-lastVisible)}
function stopTimers(){timers.forEach(clearTimeout);timers=[];running=false;catchRespond=null}
function later(fn,ms){const id=setTimeout(fn,ms);timers.push(id);return id}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function receiptRows(){const s=Math.floor(timeVisible()/1000);return [['Page visible',`${Math.floor(s/60)}m ${s%60}s`],['Exercises completed',`${['search','stroop','catch'].filter(k=>state[k]).length} / 3`],['Photo details recalled',state.recall===null?'Not tried':`${state.recall} / 3`],['Quiet / busy search',state.search?`${state.search.quiet}s / ${state.search.busy}s`:'Not tried'],['Search wrong selections',state.search?String(state.search.errors):'Not yet'],['Colour accuracy',state.stroop?`${state.stroop.accuracy}%`:'Not tried'],['Colour response difference',state.stroop?`${state.stroop.difference} ms`:'Not yet'],['Exception: missed targets',state.catch?`${state.catch.misses} / ${state.catch.targets}`:'Not tried'],['Exception: accidental taps',state.catch?`${state.catch.falseTaps} / ${state.catch.exceptions}`:'Not yet'],['Exception: median response',state.catch?`${state.catch.median} ms`:'Not yet'],['Felt distracted',$('#distraction').value]]}
function updateReceipt(){const root=$('#receipt-data');root.replaceChildren();receiptRows().forEach(([a,b])=>{const row=document.createElement('div');row.className='receipt-row';for(const t of [a,b]){const span=document.createElement('span');span.textContent=t;row.append(span)}root.append(row)})}
setInterval(updateReceipt,5000);$('#distraction').onchange=updateReceipt;
document.addEventListener('visibilitychange',()=>{if(document.hidden){visibleMs+=performance.now()-lastVisible;if(running){stopTimers();intro(active,'Round paused because you left the page. Start again when you’re ready.')}}else lastVisible=performance.now()});
$('#recall-start').onclick=()=>{const r=$('#recall');r.hidden=false;$('#photo-frame').hidden=true;$('#recall-start').hidden=true;r.innerHTML='<h3>What stayed with you?</h3><p>Three details. Go with what you remember.</p><form id="recall-form">'+[['What was someone holding?',['An umbrella','A balloon','A suitcase']],['Where was the bicycle?',['On the left','On the right','There was no bicycle']],['What was the street like?',['Wet and reflective','Dry and dusty','Covered in snow']]].map(([q,opts],i)=>`<fieldset><legend>${q}</legend>${opts.map((v,j)=>`<label><input type="radio" name="q${i}" value="${j}" required>${v}</label>`).join('')}</fieldset>`).join('')+'<button class="dark-button">See what you noticed →</button></form>';$('#recall-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.recall=[0,1,2].filter(i=>d.get('q'+i)==='0').length;r.innerHTML=`<p class="recall-feedback" tabindex="-1">You recalled ${state.recall} of 3 details.</p><p>An umbrella near the centre. A bicycle on the left. A wet, reflective street.</p><p>Looking and remembering work together. This is a glimpse of this moment, not a verdict on your attention.</p><a class="dark-button" href="#economy">Follow the attention →</a>`;$('#photo-frame').hidden=false;setPostcardType('moment-type',true);updateReceipt();$('.recall-feedback').focus()};r.scrollIntoView({block:'center'})};
const descriptions={search:['Find the quiet thing','Two rounds · about 30 sec','Find and select the small four-point star ✦. First among quiet symbols, then among louder words. We’ll show the time and wrong selections for each layout.'],stroop:['Read the colour','24 trials · about 45 sec','Choose the ink colour, even when the word says something else. Use the labelled buttons or keys 1 to 4. Your first four trials are practice and won’t count.'],catch:['Catch the exception','30 trials · about 45 sec','Tap the large button (or press Space) for every number EXCEPT 3. When 3 appears, do nothing. Each number is followed by a brief blank. Keep watching.']};
function intro(type,message=''){stopTimers();active=type;document.querySelectorAll('[data-game]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.game===type));b.tabIndex=b.dataset.game===type?0:-1});game.setAttribute('aria-labelledby','tab-'+type);const [title,duration,desc]=descriptions[type];game.innerHTML=`<div class="game-head"><h3>${title}</h3><span>${duration}</span></div><p class="game-desc">${desc}</p>${message?`<p role="status">${message}</p>`:''}<div class="start-row"><button class="dark-button" id="start-game">${state[type]?'Play again':'Try it'} →</button></div><p class="game-desc">${type==='search'?'The rounds differ in layout and order. Their difference isn’t a scientific estimate of distraction.':type==='stroop'?'We compare your correct responses when word and colour agree with when they conflict.':'A short demonstration inspired by sustained-attention response tasks.'}</p>`;$('#start-game').onclick=()=>({search:startSearch,stroop:startStroop,catch:startCatch}[type]())}
document.querySelectorAll('[data-game]').forEach((b,i,all)=>{b.onclick=()=>intro(b.dataset.game);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const n=(i+(e.key==='ArrowRight'?1:all.length-1))%all.length;all[n].focus();intro(all[n].dataset.game)}}});
function results(title,metrics,copy,type){stopTimers();game.innerHTML=`<div class="game-head"><h3 tabindex="-1">${title}</h3><span>THIS ROUND</span></div><div class="result-metrics">${metrics.map(([v,l])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><p class="game-desc">${copy}</p><button class="dark-button" id="again">Play again ↻</button> <a class="answer-button" href="#receipt">See your receipt</a>`;$('#again').onclick=()=>intro(type);updateReceipt();game.querySelector('h3').focus()}
function startSearch(){running=true;let round=0,start,errors=0,times=[],roundErrors=0;function draw(){const busy=round===1,target=Math.floor(Math.random()*24);game.innerHTML=`<div class="game-head"><h3>Find ✦</h3><span>${busy?'BUSY':'QUIET'} ROUND · ${round+1}/2</span></div><p>Select the four-point star. Wrong selections: <span id="wrong">0</span></p><div class="search-board ${busy?'busy':''}">${Array.from({length:24},(_,i)=>`<button aria-label="${i===target?'Four-point star':busy?'Distracting word':'Other symbol'}">${i===target?'✦':busy?['SALE','HEY!','NEW','LOOK','99+','WATCH'][Math.floor(Math.random()*6)]:['○','＋','△','□'][Math.floor(Math.random()*4)]}</button>`).join('')}</div>`;start=performance.now();document.querySelectorAll('.search-board button').forEach((b,i)=>b.onclick=()=>{if(i!==target){roundErrors++;errors++;$('#wrong').textContent=roundErrors;return}times.push(((performance.now()-start)/1000).toFixed(1));if(round===0){round++;roundErrors=0;game.innerHTML='<h3>One found. Now add some noise.</h3><p>The next layout contains competing words. Find the same star.</p><button class="dark-button" id="next-round">Begin busy round →</button>';$('#next-round').onclick=draw}else{state.search={quiet:times[0],busy:times[1],errors};results('Same target. Different surroundings.',[[times[0]+'s','Quiet layout'],[times[1]+'s','Busy layout'],[errors,'Wrong selections']],'These are your two completion times. Target placement, practice and chance also contribute to any difference.','search')}})}draw()}
const colours=[['RED','#c62a21'],['BLUE','#2449ea'],['GREEN','#187444'],['PURPLE','#883cab']];let colourResponse=null;
function startStroop(){running=true;let index=0,started,ready=false,records=[];const scored=shuffle(Array.from({length:20},(_,i)=>{const colour=i%4;return{colour,word:i<10?colour:(colour+1+Math.floor(Math.random()*3))%4}}));const trials=[{colour:0,word:0},{colour:1,word:2},{colour:2,word:2},{colour:3,word:0},...scored];function draw(){ready=true;const t=trials[index];game.innerHTML=`<div class="game-head"><h3>Choose the ink colour.</h3><span>${index<4?'PRACTICE':'SCORED ROUND'}</span></div><div class="stimulus" style="color:${colours[t.colour][1]}">${colours[t.word][0]}</div><div class="colour-options">${colours.map(([c],i)=>`<button data-colour="${i}">${i+1} · ${c}</button>`).join('')}</div><div class="game-progress">${index+1} / 24 · Four practice trials, then twenty scored.</div>`;started=performance.now();document.querySelectorAll('[data-colour]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.colour)))}function answer(c){if(!running||active!=='stroop'||!ready)return;ready=false;const t=trials[index];if(index>=4)records.push({correct:c===t.colour,ms:performance.now()-started,match:t.colour===t.word});index++;if(index===trials.length){colourResponse=null;const correct=records.filter(x=>x.correct);const mean=a=>a.length?a.reduce((s,x)=>s+x.ms,0)/a.length:null;const a=mean(correct.filter(x=>x.match)),b=mean(correct.filter(x=>!x.match));const difference=a===null||b===null?'N/A':Math.round(b-a);state.stroop={accuracy:Math.round(correct.length/20*100),difference};results('Words can pull in another direction.',[[state.stroop.accuracy+'%','Correct responses'],[difference==='N/A'?'N/A':(difference>0?'+':'')+difference+' ms','Conflict minus matching time']],'Timing uses correct trials only. A positive difference means conflicting words took longer this round; a negative difference means they were faster. Short sessions are noisy.','stroop')}else{game.querySelector('.stimulus').textContent='·';later(draw,200)}}colourResponse=answer;draw()}
function startCatch(){running=true;let i=0,current=null,responded=false,started=0,misses=0,falseTaps=0,rts=[];const trials=shuffle([...Array.from({length:24},(_,i)=>[1,2,4,5,6,7,8,9][i%8]),...Array(6).fill(3)]);game.innerHTML='<div class="game-head"><h3>Every number. Except 3.</h3><span>SPACE OR TAP</span></div><div class="stimulus" id="digit" aria-live="off">Ready</div><button class="catch-button" id="tap">Tap for every number except 3</button><div class="game-progress" id="catch-progress">Get ready…</div>';function finishTrial(){if(current!==3&&!responded)misses++;current=null;i++;if(i>=trials.length){const sorted=[...rts].sort((a,b)=>a-b);const n=sorted.length;const median=n?Math.round(n%2?sorted[Math.floor(n/2)]:(sorted[n/2-1]+sorted[n/2])/2):'N/A';state.catch={misses,falseTaps,targets:24,exceptions:6,median};results('Sometimes the task is not to tap.',[[misses,'Missed targets / 24'],[falseTaps,'Accidental taps / 6'],[median==='N/A'?'N/A':median+' ms','Median correct response']],'A brief snapshot of responses and restraint. This is a shortened adaptation, not a clinical test or a reliable measure of your general attention.','catch')}else show()}function show(){current=trials[i];responded=false;started=performance.now();$('#digit').textContent=current;$('#catch-progress').textContent=`${i+1} / 30`;later(()=>{if($('#digit'))$('#digit').textContent='·'},550);later(finishTrial,1300)}catchRespond=()=>{if(current===null||responded||!running)return;responded=true;if(current===3)falseTaps++;else rts.push(performance.now()-started);$('#tap').textContent='Recorded';later(()=>{if($('#tap'))$('#tap').textContent='Tap for every number except 3'},180)};$('#tap').onclick=catchRespond;later(show,1500)}
document.addEventListener('keydown',e=>{if(e.repeat||!running||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(active==='stroop'&&colourResponse&&['1','2','3','4'].includes(e.key)){e.preventDefault();colourResponse(Number(e.key)-1)}if(active==='catch'&&e.code==='Space'&&catchRespond){e.preventDefault();catchRespond()}});
$('#download').onclick=()=>{updateReceipt();const lines=['PAY ATTENTION.','YOUR ATTENTION RECEIPT','',...receiptRows().map(([a,b])=>`${a}: ${b}`),'','TOTAL VALUE: YOURS.','Notice one thing you usually walk past.','Page-visible time is not proof of attention.','This receipt measures a visit. It does not measure a person.'];const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1190;const c=canvas.getContext('2d');c.fillStyle='#f4f3ef';c.fillRect(0,0,900,1190);c.fillStyle='#2449ea';c.fillRect(0,0,900,16);c.fillStyle='#181818';let y=80;lines.forEach((l,i)=>{c.font=i===0?'bold 50px sans-serif':i===1?'22px monospace':'20px monospace';c.fillText(l,50,y);y+=i===0?55:44});canvas.toBlob(b=>{if(!b)return;const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='my-attention-receipt.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)},'image/png')};
function setPostcardType(id,hidden){const layer=document.getElementById(id);if(!layer)return;layer.classList.toggle('words-away',hidden);const button=document.querySelector(`[data-type="${id}"]`);if(button){button.setAttribute('aria-pressed',String(hidden));button.textContent=hidden?'Bring the words back':'Let the words go'}}
document.querySelectorAll('[data-type]').forEach(button=>button.onclick=()=>setPostcardType(button.dataset.type,button.getAttribute('aria-pressed')!=='true'));
let pauseTimer;$('#pause-button').onclick=()=>{clearInterval(pauseTimer);const began=performance.now();$('#pause-button').disabled=true;$('.ending').classList.add('quiet-moment');$('#pause-status').textContent='Look away. There is nothing here you need to wait for.';pauseTimer=setInterval(()=>{if(performance.now()-began>=30000){clearInterval(pauseTimer);$('#pause-status').textContent='Let something ordinary be enough.';$('#pause-button').disabled=false;$('#pause-button').textContent='Take another moment ↗'}},500)};
intro('search');updateReceipt();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_attention_receipt',description:'Read the current visit’s exercise results and page-visible time. Does not perform or answer the exercises.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('No parameters expected');return Object.fromEntries(receiptRows())}})).catch(()=>{})}catch{}}
